"""Validate finite contract coverage, hash evidence, and write compact handoff."""
from pathlib import Path
import csv,hashlib,json,resource,time
import numpy as np
H=Path(__file__).resolve().parent

def read(p):return json.loads((H/p).read_text())
def write(p,o):(H/p).write_text(json.dumps(o,indent=2,allow_nan=False)+'\n')
def sha(p):
 h=hashlib.sha256()
 with p.open('rb') as f:
  for b in iter(lambda:f.read(4*1024*1024),b''):h.update(b)
 return h.hexdigest()
